const result = global.get('parseReading')(msg.topic, msg.payload);
if (result.error) {
    node.warn(`Ditolak ${msg.topic}: ${result.error} | ${String(msg.payload).slice(0, 200)}`);
    return null;
}
msg.reading = result.reading;
return msg;

const result = await global.get('saveReading')(global.get('pg'), msg.reading);
if (result.warn) node.warn(`Ditolak ${msg.topic}: ${result.warn}`);
else node.log(result.log);
return null;

// Salinan setiap pesan apa adanya (termasuk yang ditolak), bahan latih ulang model.
// ponytail: satu objek per pesan (~5.760/hari untuk 4 node); gabung per jam ke JSONL bila jumlah objek jadi masalah
const minio = global.get('minio');
const bucket = global.get('rawBucket');
const received = new Date().toISOString();
const node_id = msg.topic.split('/')[1];
const key = `${node_id}/${received.slice(0, 10)}/${received.slice(11, 23).replace(/:/g, '')}-${msg._msgid}.json`;
const body = Buffer.from(msg.payload);
const meta = { 'Content-Type': 'application/json', 'x-amz-meta-topic': msg.topic, 'x-amz-meta-received': received };
try {
    await minio.putObject(bucket, key, body, body.length, meta);
} catch (err) {
    if (err.code !== 'NoSuchBucket') throw err;
    // pesan pertama bisa datang bersamaan, jadi bucket mungkin sudah dibuat pesan lain
    await minio.makeBucket(bucket).catch(e => { if (e.code !== 'BucketAlreadyOwnedByYou') throw e; });
    await minio.putObject(bucket, key, body, body.length, meta);
}
return null;

const parsed = global.get('parseLevel')(msg.topic, msg.payload);
if (parsed.error) {
    node.warn(`Ditolak ${msg.topic}: ${parsed.error} | ${String(msg.payload).slice(0, 200)}`);
    return null;
}
const result = await global.get('saveLevel')(global.get('pg'), parsed.level);
if (result.warn) node.warn(result.warn);
else node.log(result.log);
return null;
